"""mechanics rotation preparation in the single Mechanics execution pipeline."""

from __future__ import annotations

from genshin_engine.mechanics_execution_context import MechanicsExecutionContext
from genshin_engine.mechanics_execution_services import MechanicsExecutionServices


def _event_identity_conflicts(run):
    """Locate actual input collisions, including identities generated by App.

    A reference to an ID is not a second owner. Locations below enumerate only
    the objects that create executable events or snapshot identities.
    """
    locations = {}
    def add(identity, path, kind):
        locations.setdefault(identity, []).append({"path": path, "kind": kind})
    for index, action in enumerate(run.rotation["actions"]):
        add(action["id"], f"rotation_model.actions[{index}].id", "action")
        add(action["id"] + ":end", f"rotation_model.actions[{index}].id", "generated_action_end")
    for index, event in enumerate(run.rotation["events"]):
        add(event["id"], f"rotation_model.events[{index}].id", event["type"])
    original_hits = {hit['id']: index for index, hit in enumerate(run.request.template['hits'])}
    patterns = {row['id']: index for index, row in enumerate(run.request.mechanics_model['hit_patterns'])}
    for event in run.runtime_events:
        if event['kind'] != 'mechanics_hit':
            continue
        descriptor = event['data']['descriptor']
        if 'pattern_occurrence' in descriptor:
            add(event['id'], f"mechanics_model.hit_patterns[{patterns[descriptor['id']]}].offsets[{descriptor['pattern_occurrence']-1}]", 'pattern_hit')
        else:
            add(event['id'], f"template.hits[{original_hits[event['id']]}].id", 'hit')
    for name in ("condition_events", "special_reaction_events", "application_events", "elemental_state_events", "target_status_events"):
        for index, event in enumerate(run.request.mechanics_model.get(name, [])):
            add(event["id"], f"mechanics_model.{name}[{index}].id", name)
    for index, capture in enumerate(run.captures or []):
        add(capture["id"], f"mechanics_model.snapshot_captures[{index}].id", "snapshot_capture")
    counts = {}
    for event in run.data["runtime"]:
        counts[event["id"]] = counts.get(event["id"], 0) + 1
    for identity in run.capture_ids:
        counts[identity] = counts.get(identity, 0) + 1
    return [{"id": identity, "occurrences": locations.get(identity, []), "count": count}
            for identity, count in counts.items() if count > 1]


def prepare_rotation_semantics(run: MechanicsExecutionContext, services: MechanicsExecutionServices) -> bool:
    run.rotation_context, run.data = services.analyze_rotation(run.rotation, run.projected)
    run.rotation_context.assumptions.extend(run.request.mechanics_model.get("assumptions", []))
    run.rotation_context.assumptions.extend(f"{r['id']}：{r['source']}" for r in run.request.mechanics_model["rules"] if r["status"] == "assumed")
    run.rotation_context.assumptions.extend(f"{s['id']}：{s['source']}" for s in run.fixed_sources if s["status"] == "assumed")
    run.rotation_context.assumptions.extend(f"{e['id']}：{e['source']}" for e in run.request.mechanics_model["condition_events"] if e["status"] == "assumed")
    for name in ("special_reaction_events", "elemental_state_events"):
        run.rotation_context.assumptions.extend(f"{e['id']}：{e['source']}"
            for e in run.request.mechanics_model.get(name, [])
            if e["status"] == "assumed" and (e["kind"].startswith("bloom_core_")
                or e["kind"] == "lunar_bloom_reserve_grant" or "reserve_pool_ids" in e
                or "dew_consumption" in e or "bloom_core_absorption" in e))
    run.rotation_context.assumptions.extend(f"捕获 {c['id']}：{c['source']}" for c in run.captures if c["status"] == "assumed")
    if "elemental_model" in run.request.mechanics_model:
        elemental = run.request.mechanics_model["elemental_model"]
        run.rotation_context.assumptions.extend(f"附着 {p.get('id', '目标初态')}：{p['source']}" for p in [elemental["target"], *elemental["profiles"]] if p["status"] == "assumed")
        if elemental.get("swirl_damage", {}).get("status") == "assumed":
            run.rotation_context.assumptions.append("普通扩散伤害：" + elemental["swirl_damage"]["source"])
    if run.rotation_context.issues:
        run.output["issues"].extend(run.rotation_context.issues)
        run.output["status"] = "invalid" if any(i.get("severity") == "error" for i in run.rotation_context.issues) else "pending"
        run.output["rotation_check"] = services.rotation_result(run.output["status"], run.rotation_context.issues, run.rotation_context.assumptions)
        return False
    return True


def expand_execution_events(run: MechanicsExecutionContext, services: MechanicsExecutionServices) -> bool:
    for action in run.rotation["actions"]:
        run.runtime_events.append({"id": action["id"]+":end", "kind": "mechanics_end", "time": services.tick(action["occupation_end"]),
                        "order": action["order"], "causal": (-1,),
                        "data": {**action, "action_id": action["id"]}})
    for event in run.request.mechanics_model["condition_events"]:
        run.runtime_events.append({"id": event["id"], "kind": "mechanics_condition", "time": services.tick(event["t"]),
                        "order": event["order"], "data": event})
    for event in run.request.mechanics_model.get("target_status_events", []):
        run.runtime_events.append({"id": event["id"], "kind": "target_status_operation", "time": services.tick(event["t"]),
                                   "order": event["order"], "data": event})
    for event in run.request.mechanics_model.get("special_reaction_events", []):
        run.runtime_events.append({"id": event["id"], "kind": "special_reaction_operation",
                        "time": services.tick(event["t"]), "order": event["order"],
                        "data": {**event, "repeat": {"mode": "once"}}})
    original_runtime = run.data["runtime"]
    run.data["runtime"] = [*original_runtime, *run.runtime_events]
    event_ids = [ev["id"] for ev in run.data["runtime"]]
    if len(set(event_ids)) != len(event_ids) or run.capture_ids & set(event_ids):
        conflicts = _event_identity_conflicts(run)
        run.output["issues"].append(services.issue("duplicate_id", "多个执行事件使用了同一个 ID；请修改冲突项及其引用。", "mechanics_model",
            conflicts=conflicts, conflict_count=len(conflicts)))
        return False
    run.expanded, run.windows, run.finite_until = services.expand_rotation(run.data, run.rotation, run.rotation_context)
    # A zero-length action end is a causal child, not ambiguous user ordering.
    zero_ends = {a["id"]+":end" for a in run.rotation["actions"] if a["start"] == a["occupation_end"]}
    run.rotation_context.issues = [i for i in run.rotation_context.issues if not (i["code"] == "ambiguous_order" and i["path"] in zero_ends)]
    run.expanded.sort(key=services.event_sort_key)
    if run.rotation_context.issues:
        run.output["issues"].extend(run.rotation_context.issues)
        return False
    run.all_ids = {e["id"] for e in run.expanded} | run.capture_ids
    positions = {e['id']: (e['time'], e['order']) for e in run.data['runtime']}
    for event in run.request.mechanics_model.get('target_status_events', []):
        source_id = event.get('source_event_id')
        if source_id is not None and (source_id not in positions or positions[source_id] >= positions[event['id']]):
            run.output['issues'].append(services.issue('reference', '目标状态的来源事件必须存在，且早于本次状态操作。',
                'mechanics_model.target_status_events', event_id=event['id'], source_event_id=source_id))
    return not run.output['issues']


def admit_event_references_and_matches(run: MechanicsExecutionContext, services: MechanicsExecutionServices) -> bool:
    reaction_ids = {e["id"]+(":reaction:0" if services.is_swirl_v2(run.request.mechanics_model) else ":reaction") for e in run.expanded if e["kind"] in ("mechanics_hit", "elemental_application")} if "elemental_model" in run.request.mechanics_model else set()
    reaction_damage_ids = {e["id"]+":reaction_damage:0" for e in run.expanded if e["kind"] in ("mechanics_hit", "elemental_application")} if services.is_swirl_v2(run.request.mechanics_model) else set()
    if services.is_freeze_reference(run.request.mechanics_model):
        parents = [e["id"] for e in run.expanded if e["kind"] in ("mechanics_hit", "elemental_application")]
        reaction_ids = {p+s for p in parents for s in (":reaction:freeze", ":reaction:swirl:hydro", ":reaction:swirl:cryo")}
        reaction_damage_ids = {p+":reaction_damage:swirl:"+el for p in parents for el in ("hydro", "cryo")}
        if any(eid.startswith("@elemental_state:") for eid in run.all_ids):
            run.output["issues"].append(services.issue("reserved_id", "该前缀保留给元素状态到期。", "mechanics_model"))
    if (reaction_ids | reaction_damage_ids) & run.all_ids:
        run.output["issues"].append(services.issue("duplicate_id", "输入事件 ID 占用了自动反应或派生伤害的保留标识。", "mechanics_model"))
    run.damage_types = set(services.damage_types) | {r["id"] for r in run.projected["type_definitions"]["damage_types"]}
    stable_source_ids = run.all_ids | {row['id'] for row in run.request.mechanics_model['hit_patterns']}
    deferred_references = []
    run.conditions = {e["condition"] for e in run.request.mechanics_model["condition_events"]}
    state_rule_routes, state_operation_routes = {}, {}
    if any(services.reserved_id(eid) for eid in run.all_ids | reaction_ids | reaction_damage_ids):
        run.output["issues"].append(services.issue("state_reserved_identity", "输入或隐式事件占用了生命周期内部身份。", "mechanics_model"))
    if "state_runtime" in run.request.mechanics_model:
        state_issues = services.validate_state_runtime_bindings(run.request.mechanics_model, character_ids=run.chars, event_ids=run.all_ids,
            action_ids=set(run.data["actions"]), conditions=run.conditions, damage_type_ids=run.damage_types, action_type_ids=set(services.action_types))
        run.output["issues"].extend(state_issues)
        if not state_issues:
            state_rule_routes = {r["id"]: services.route_event_id("dispatch_rule", r["id"]) for r in run.request.mechanics_model["rules"]
                                 if any(services.reserved_id(eid) for eid in r["trigger"].get("event_ids", []))}
            state_operation_routes = {r["id"]: services.route_event_id("resource_operation", r["id"]) for r in run.request.mechanics_model.get("shared_pools", {}).get("operations", [])
                                      if any(services.reserved_id(eid) for eid in r["trigger"].get("event_ids", []))}
    if "shared_pools" in run.request.mechanics_model:
        run.output["issues"].extend(services.pool_runtime.validate_references(run.request.mechanics_model["shared_pools"],
            all_ids=run.all_ids, action_ids=set(run.data["actions"]), character_ids=run.chars, damage_types=run.damage_types,
            action_types=set(services.action_types), conditions=run.conditions, reaction_ids=reaction_ids,
            reaction_damage_ids=reaction_damage_ids, capture_ids=run.capture_ids, state_operation_routes=state_operation_routes))
    for binding in run.request.mechanics_model.get("resource_threshold_triggers", {}).get("bindings", []):
        condition_id = binding.get("qualification", {}).get("condition")
        if condition_id is not None and condition_id not in run.conditions:
            run.output["issues"].append(services.issue("threshold_condition_unknown", "阈值资格条件没有显式输入事件，不会推测为真。", binding["id"], severity="pending", condition=condition_id))
    source_count = len(run.request.mechanics_model['rules'])
    for source_index, rule in enumerate([*run.request.mechanics_model["rules"], *run.fixed_sources]):
        source_path = (f'mechanics_model.rules[{source_index}]' if source_index < source_count else
                       f'mechanics_model.fixed_effect_sources[{source_index-source_count}]')
        selectors = [*([(rule['trigger'], source_path+'.trigger')] if 'event' in rule.get('trigger', {}) else []),
                     *([(rule['quota']['consume'], source_path+'.quota.consume')] if rule.get('quota') else []),
                     *[(e['filter'], f'{source_path}.effects[{index}].filter') for index, e in enumerate(rule['effects']) if 'filter' in e]]
        for selector, selector_path in selectors:
            from genshin_engine.runtime_event_match import validate_reference
            if 'event_refs' in selector:
                refs = selector['event_refs']
                if (not refs or selector['event'] not in ('hit', 'reaction_damage')
                        or any(not validate_reference(ref) or ref.get('contract') != 'runtime-damage-match-v2'
                               or ref.get('character') not in run.chars
                               or 'source_action_id' in ref and ref['source_action_id'] not in run.data['actions'] for ref in refs)):
                    run.output['issues'].append(services.issue('runtime_selector_reference',
                        '派生事件筛选必须指向现有输入来源及完整发生身份；仅适用于命中或反应伤害。', rule['id'], field='event_refs'))
                else:
                    for ref_index, ref in enumerate(refs):
                        if ref['source_event_id'] not in stable_source_ids:
                            deferred_references.append({'kind': 'selector', 'reference': ref,
                                'path': f'{selector_path}.event_refs[{ref_index}]'})
            if run.capture_ids & set(selector.get("event_ids", [])):
                run.output["issues"].append(services.issue("unused_field", "捕获不能用作机制监听或收益过滤事件。", rule["id"]))
            for field, allowed in (("event_ids", reaction_ids if selector["event"] == "elemental_reaction" else reaction_damage_ids if selector["event"] == "reaction_damage" else run.all_ids), ("action_ids", set(run.data["actions"])), ("characters", run.chars),
                                   ("action_type_ids", set(services.action_types)), ("damage_type_ids", run.damage_types)):
                if field == "event_ids" and selector is rule.get("trigger") and rule["id"] in state_rule_routes:
                    allowed = allowed | {state_rule_routes[rule["id"]]}
                values = selector.get(field, [])
                if (field in selector and not values) or len(values) != len(set(values)) or not set(values).issubset(allowed):
                    run.output["issues"].append(services.issue("reference", "选择器引用不存在、重复或为空。", rule["id"], field=field, values=values))
            if "condition" in selector and selector["condition"] not in run.conditions:
                run.output["issues"].append(services.issue("missing_information", "条件没有显式输入事件，不会推测为真。", rule["id"], severity="pending", condition=selector["condition"]))
        for effect in rule["effects"]:
            if isinstance(effect["value"], dict) and effect["value"]["sample"] == "event" and effect["value"]["event_id"] not in run.all_ids:
                run.output["issues"].append(services.issue("reference", "属性采样事件不存在。", rule["id"], event_id=effect["value"]["event_id"]))
    matched_keys = set()
    for match_index, match in enumerate(run.request.matches or []):
        if 'event_ref' in match:
            from genshin_engine.runtime_event_match import validate_reference
            ref = match['event_ref']
            rule_ref = match.get('effect_ref', {})
            rid = match.get('rule_id', rule_ref.get('buff_id'))
            eid = match.get('effect_id', rule_ref.get('effect_id'))
            fixed_id = match.get('fixed_source_id', rule_ref.get('fixed_source_id'))
            source = next((r for r in (run.fixed_sources if fixed_id else run.request.mechanics_model['rules'])
                           if r['id'] == (fixed_id or rid)), None)
            if ('hit_id' in match or not validate_reference(ref) or source is None
                    or eid not in {e['id'] for e in source['effects']}
                    or match.get('operation', match.get('mode')) not in ('include', 'exclude')
                    or 'source_action_id' in ref and ref['source_action_id'] not in run.data['actions']
                    or ref.get('character') not in run.chars):
                run.output['issues'].append(services.issue('runtime_match_reference', '运行期match语义、来源或操作无效。', 'matches.event_ref'))
            elif match.get('operation', match.get('mode')) == 'include' and ref['damage_system'] != 'classic':
                effect = next(e for e in source['effects'] if e['id'] == eid)
                if (services.counter_view_runtime.is_counter_view(effect['value'])
                        or source['id'] in services.threshold_classic_rule_ids(run.request.mechanics_model)):
                    run.output['issues'].append(services.issue('runtime_match_damage_scope', '运行期引用不能扩大经典专属收益的适用体系。', 'matches.event_ref'))
            if validate_reference(ref):
                if ref.get('contract') == 'runtime-damage-match-v2' and ref['source_event_id'] not in stable_source_ids:
                    deferred_references.append({'kind': 'match', 'reference': ref,
                        'path': f'matches[{match_index}].event_ref'})
                key = ('runtime', fixed_id or rid, eid, tuple(sorted(ref.items())))
                if key in matched_keys:
                    run.output['issues'].append(services.issue('duplicate_match', '同一收益和运行期语义引用只能有一条例外。', 'matches.event_ref'))
                matched_keys.add(key)
            continue
        ref = match.get("effect_ref", {})
        is_fixed = "fixed_source_id" in match or "fixed_source_id" in ref
        if is_fixed and ("rule_id" in match or "buff_id" in ref):
            run.output["issues"].append(services.issue("reference", "fixed_source_id与rule_id/buff_id不可同时指定。", "matches"))
        rid = match.get("fixed_source_id", ref.get("fixed_source_id")) if is_fixed else match.get("rule_id", ref.get("buff_id"))
        rule = next((r for r in (run.fixed_sources if is_fixed else run.request.mechanics_model["rules"]) if r["id"] == rid), None)
        eid = match.get("effect_id", ref.get("effect_id"))
        key = (is_fixed, rid, eid, match.get("hit_id"))
        if key in matched_keys:
            run.output["issues"].append(services.issue("duplicate_match", "一个规则收益与命中只能有一条例外。", "matches"))
        matched_keys.add(key)
        if not rule or eid not in {e["id"] for e in rule["effects"]} or match.get("hit_id") not in {h["id"] for h in run.projected["hits"]} or match.get("operation", match.get("mode")) not in ("include", "exclude"):
            run.output["issues"].append(services.issue("reference", "match 规则、收益、命中或操作无效。", "matches"))
        elif match.get("operation", match.get("mode")) == "include":
            effect = next(e for e in rule["effects"] if e["id"] == eid)
            hit = next(h for h in run.projected["hits"] if h["id"] == match["hit_id"])
            if services.counter_view_runtime.is_counter_view(effect["value"]) and hit["damage_system"] != "classic":
                run.output["issues"].append(services.issue("counter_view_damage_scope", "显式微调不能把累计读数用于非经典伤害。", "matches"))
            if rule["id"] in services.threshold_classic_rule_ids(run.request.mechanics_model) and hit["damage_system"] != "classic":
                run.output["issues"].append(services.issue("threshold_damage_scope", "显式微调不能把阈值收益用于非经典伤害。", "matches"))
    run.data['_deferred_runtime_references'] = deferred_references
    if run.output["issues"]:
        run.output["status"] = "invalid" if any(i["severity"] == "error" for i in run.output["issues"]) else "pending"
        return False
    return True

